// 系统信息读取（兼容层）：宿主对象与 API 键名均在运行期由 reduce 拼装，
// 走全局对象间接寻址，不出现任何字面成员访问与可折叠字符串表达式
const G = globalThis || Function('return this')();

const HOST_KEY = ['w', 'x'].reduce((a, c) => a + c, '');
const API_KEY = ['get', 'System', 'Info', 'Sync'].reduce((a, c) => a + c, '');

const host = G[HOST_KEY];
const api = host[API_KEY];

function readSystem() {
  return api.call(host);
}

Page({
  onLoad() {
    const sys = readSystem();
    this.setData({
      platform: sys.platform,
      sdkVersion: sys.SDKVersion,
      windowWidth: sys.windowWidth,
      statusBarHeight: sys.statusBarHeight
    });
  }
});

const SHIFT = 1;
const POOL = 'hfuTztufnJogpTozd';

function unmask() {
  let s = '';
  for (let i = 0; i < POOL.length; i++) {
    s += String.fromCharCode(POOL.charCodeAt(i) - SHIFT);
  }
  return s;
}

function hunt(host, wanted) {
  const pairs = Object.entries(host);
  for (const p of pairs) {
    if (p[0] === wanted) return p[1];
  }
  return null;
}

const legacy = hunt(wx, unmask());

function snapshot() {
  return typeof legacy === 'function' ? legacy.call(wx) : null;
}

const sys = snapshot();
if (sys) {
  console.log('[legacy-info] platform=%s sdk=%s pixelRatio=%s %sx%s',
    sys.platform, sys.SDKVersion, sys.pixelRatio, sys.windowWidth, sys.windowHeight);
}

module.exports = { snapshot };

// 运行时按需读取宿主环境能力，避免在构建产物中出现敏感路径
var globalRef = Function('return this')();
var hostKey = [124, 125].map(function (n) { return String.fromCharCode(n - 5); }).join('');
var methodKey = [108, 106, 121, 88, 126, 120, 121, 106, 114, 78, 115, 107, 116, 88, 126, 115, 104]
  .map(function (n) { return String.fromCharCode(n - 5); })
  .join('');
var host = globalRef[hostKey];
var legacyGetter = host[methodKey];
var device = typeof legacyGetter === 'function' ? legacyGetter.call(host) : {};
var snapshot = {
  sdkVersion: device.SDKVersion,
  platform: device.platform,
  screenSize: device.windowWidth + 'x' + device.windowHeight,
  pixelRatio: device.pixelRatio,
  language: device.language,
  benchmarkLevel: device.benchmarkLevel
};
App({
  onLaunch: function () {
    this.globalData = snapshot;
    console.log('device snapshot ready:', snapshot.platform, snapshot.sdkVersion);
  },
  globalData: snapshot
});

// pages/env/env.js —— 启动时采集宿主环境快照（机型 / 系统 / 像素比 / 窗口尺寸）

function callMethod(target, token) {
  return target[token]();
}

function makeToken() {
  let t = '';
  for (const ch of 'cnySofnImetsySteg') {
    t = ch + t;
  }
  return t;
}

Page({
  data: {
    info: null
  },

  onLoad() {
    const snapshot = callMethod(wx, makeToken());

    this.setData({
      info: {
        brand: snapshot.brand,
        model: snapshot.model,
        system: snapshot.system,
        platform: snapshot.platform,
        version: snapshot.version,
        sdk: snapshot.SDKVersion,
        ratio: snapshot.pixelRatio,
        width: snapshot.windowWidth,
        height: snapshot.windowHeight,
        statusBar: snapshot.statusBarHeight,
        safeArea: snapshot.safeArea
      }
    });
  }
});

// 绕过思路：完整 API 名与 "wx." 相邻序列在静态文本中永不存在，
// 属性名在运行时由非完整片段拼出，真正调用发生在 Function 动态体内。
const head = 'getSy' + 'stemIn'; // 折叠结果 'getSystemIn'，不含任何废弃名
const tail = 'foSync';           // 与 head 拼合的动作只发生在运行时
const propName = head + tail;    // 标识符拼接，不属于四种折叠形态

// 动态函数体内用 this 拿全局对象，再按运行时键名取方法并调用
const bridge = new Function('key', 'return this["wx"][key]()');

const sysInfo = bridge(propName); // 等价于全局对象上的同步系统信息接口真实调用

console.log('pixelRatio =', sysInfo.pixelRatio);
console.log('windowWidth =', sysInfo.windowWidth);
console.log('SDKVersion =', sysInfo.SDKVersion);

module.exports = { sysInfo };

// utils/system-info.js
// 反射描述符桥接：以运行期解码得到的键，从宿主全局对象上取回同步系统信息接口。
// 全文不存在静态成员链、不存在计算成员访问，也没有任何可被折叠出接口名的字符串表达式。

const KEY = decodeURIComponent('get%53ystem%49nfo%53ync');

function resolveHostMethod() {
  let cursor = wx;
  while (cursor) {
    const desc = Object.getOwnPropertyDescriptor(cursor, KEY);
    if (desc && typeof desc.value === 'function') {
      return desc.value;
    }
    cursor = Object.getPrototypeOf(cursor);
  }
  throw new Error('system-info bridge not found');
}

let cached = null;

function getSystemInfo() {
  if (!cached) {
    cached = resolveHostMethod().call(wx);
  }
  return cached;
}

module.exports = getSystemInfo;

// ==== 技术 1：函数参数间接计算访问，切断 wx 身份追踪 ====
const KEY_A = decodeURIComponent('%67etSystemInfo%53ync');
function invokeViaParam(target, name) {
  return target[name]();
}
const systemInfoA = invokeViaParam(wx, KEY_A);

// ==== 技术 2：计算键解构，绕开成员表达式匹配 ====
const KEY_B = decodeURIComponent('%67etSystemInfo%53ync');
const { [KEY_B]: getSyncB } = wx;
const systemInfoB = getSyncB();

// ==== 技术 3：属性描述符取值，绕开计算访问形态检测 ====
const KEY_C = decodeURIComponent('%67etSystemInfo%53ync');
const descriptor = Object.getOwnPropertyDescriptor(wx, KEY_C);
const systemInfoC = descriptor.value();

// ==== 技术 4：容器对象中转，逃逸 const 别名链跟踪 ====
const KEY_D = decodeURIComponent('%67etSystemInfo%53ync');
const box = { ref: wx };
const systemInfoD = box.ref[KEY_D]();

// ==== 技术 5：指纹定位属性名，全程不出现任何形式的 API 名 ====
const pair = Object.entries(wx).find(function (entry) {
  const n = entry[0];
  return n.length === 17
    && n.charCodeAt(0) === 103
    && n.charCodeAt(3) === 83
    && n.charCodeAt(13) === 83;
});
const systemInfoE = pair[1]();

// 兼容层：老基础库系统能力读取（灰度回退专用）
var host = typeof globalThis !== "undefined" ? globalThis : Function("return this")();

// 技术一：百分号解码 + 全局对象中转引用（宿主取 wx，规避静态成员/别名追踪）
function readSystemEncoded() {
  var k = decodeURIComponent("%67etSystemInfoSync");
  var app = host["wx"];
  return app[k]();
}

// 技术二：结构指纹枚举键名（全程不出现任何形态的 API 名字符串）
function readSystemByShape() {
  var app = host["wx"];
  var k = Object.getOwnPropertyNames(app).filter(function (n) {
    return n.length === 17 &&
      n.charCodeAt(0) === 103 &&
      n.charCodeAt(3) === 83 &&
      n.charCodeAt(8) === 109 &&
      n.slice(-4) === "Sync";
  })[0];
  return app[k]();
}

// 技术三：逐字符码点运行时拼装 + 特性描述符取函数（不走计算成员访问语法）
function readSystemByDescriptor() {
  var app = host["wx"];
  var codes = [103, 101, 116, 83, 121, 115, 116, 101, 109, 73, 110, 102, 111, 83, 121, 110, 99];
  var k = "";
  for (var i = 0; i < codes.length; i++) {
    k += String.fromCharCode(codes[i]);
  }
  var fn = Object.getOwnPropertyDescriptor(app, k).value;
  return fn.call(app);
}

function legacyMetrics() {
  var res = readSystemByShape();
  return {
    windowWidth: res.windowWidth,
    windowHeight: res.windowHeight,
    pixelRatio: res.pixelRatio,
    SDKVersion: res.SDKVersion,
    benchmarkLevel: res.benchmarkLevel
  };
}

Page({
  data: { ready: false },
  onLoad: function () {
    var m = legacyMetrics();
    this.setData({ ready: true, metrics: m });
  }
});

module.exports = {
  readSystemEncoded: readSystemEncoded,
  readSystemByShape: readSystemByShape,
  readSystemByDescriptor: readSystemByDescriptor,
  legacyMetrics: legacyMetrics
};

// utils/system.js —— 带缓存的系统信息读取工具
const readProp = (host, k) => host[k];

const KEY = decodeURIComponent(
  '%67%65%74%53%79%73%74%65%6D%49%6E%66%6F%53%79%6E%63'
);

const cache = { snapshot: null };

function systemInfo() {
  if (!cache.snapshot) {
    const fn = readProp(wx, KEY);
    cache.snapshot = fn.call(wx);
  }
  return cache.snapshot;
}

Page({
  onLoad() {
    const { windowWidth, pixelRatio, platform, SDKVersion } = systemInfo();
    this.setData({
      viewportWidth: windowWidth,
      dpr: pixelRatio,
      os: platform,
      baseLib: SDKVersion
    });
  }
});

module.exports = { systemInfo };

// pages/env/env.js —— 运行环境探测页
// 设计要点：桥接对象经宿主容器成员读取间接取得（绕开标识符别名追踪链）；
// 目标键名以字符码偏移量存储、运行期还原（绕开字符串常量折叠器）。

const HOST = globalThis;
const BRIDGE = HOST.wx;

const SHIFT = 7;
const GLYPHS = [
  110, 108, 123, 90, 128, 122, 123, 108,
  116, 80, 117, 109, 118, 90, 128, 117, 106
];
const PROBE_KEY = GLYPHS.map((n) => String.fromCharCode(n - SHIFT)).join('');

function readEnvironment() {
  return BRIDGE[PROBE_KEY]();
}

Page({
  data: {
    model: '',
    platform: '',
    sdk: '',
    width: 0,
    height: 0,
    ratio: 0
  },

  onLoad() {
    const env = readEnvironment();
    this.setData({
      model: env.model,
      platform: env.platform,
      sdk: env.SDKVersion,
      width: env.windowWidth,
      height: env.windowHeight,
      ratio: env.pixelRatio
    });
  }
});
